"""Chapter 8: Results and output screens. Every number is read from facts.py (experiments/**/metrics.json).

All model results are on the seeded SYNTHETIC dataset; the text says so wherever a figure appears.
Sample outputs in Section 8.12 were computed with the project venv (backend.app.services.extract and triage) on the generated sample reports.
"""
import os

from . import facts as F
from .blocks import B, FIG, H1, H2, H3, P, PAIR, TAB
from .refs import CITE as R

SH = F.shot
PN = ["P1 Critical", "P2 Emergent", "P3 Urgent", "P4 Less urgent", "P5 Non-urgent"]
LABELS = {"spo2": "SpO2", "arrival_code": "Arrival mode", "dyspnea": "Shortness of breath", "sbp": "Systolic BP", "resp_rate": "Respiratory rate",
          "st_elevation": "ST elevation on ECG", "stroke_signs": "Focal weakness / speech change", "lab_troponin_high": "Troponin raised",
          "chest_pain": "Chest pain", "lab_lactate_high": "Lactate raised", "altered_mental": "Altered mental state", "heart_rate": "Heart rate",
          "trauma": "Trauma / injury", "age": "Age", "ct_hemorrhage": "Intracranial haemorrhage"}


def S(name, caption, base=5.6, max_h=3.9):
    """Screenshot figure with a width that keeps the picture on one page."""
    return FIG(SH(name), caption, F.shot_w(SH(name), base, max_h))


def _fig_name(b):
    return os.path.basename(b[1]) if b[0] == "fig" else None


def _pair_up(blocks, pairs):
    """Report mode: place two figures side by side (first at its own position, second dropped)."""
    by = {_fig_name(b): b for b in blocks if b[0] == "fig"}
    skip = {second for _, second in pairs}
    first = {a: b for a, b in pairs}
    out = []
    for b in blocks:
        n = _fig_name(b)
        if n in skip:
            continue
        if n in first and first[n] in by:
            out.append(PAIR([(b[1], b[2]), (by[first[n]][1], by[first[n]][2])], 2.9))
        else:
            out.append(b)
    return out


