def _headline():
    cm = F.CM
    rows = []
    for i in range(5):
        col = sum(cm[r][i] for r in range(5))
        prec = cm[i][i] / col if col else 0.0
        rec = F.REC[i]
        f1 = 2 * prec * rec / (prec + rec) if prec + rec else 0.0
        rows.append([PN[i], str(F.SUP[i]), F.pct(rec), F.pct(prec), F.f3(f1)])
    cm_rows = [[PN[i]] + [str(v) for v in cm[i]] + [str(sum(cm[i]))] for i in range(5)]
    return [
        H2("8.3 Triage model performance (synthetic hold-out)"),
        P(f"On the {F.N_TEST:,} held-out synthetic cases the shipped model assigns the recorded priority exactly in **{F.pct(F.ACC, 2)}** of cases and within one level in **{F.pct(F.W1, 2)}**. "
          f"The macro F1 is {F.f3(F.MF1)}, the quadratic weighted kappa {F.f3(F.QWK)} and the top-2 accuracy (recorded priority among the two most probable) {F.pct(F.TOP2)}. Mean confidence is {F.f3(F.MEAN_CONF)}, close to the accuracy, as a calibrated model should give. "
          f"Without calibration the same trees reach {F.pct(F.ACC_UNCAL, 2)} accuracy and a macro F1 of {F.f3(F.MF1_UNCAL)}, so calibration cost nothing in accuracy. Training took {F.TRAIN_SEC:.2f} s on the CPU."),
        TAB("Shipped model: per-priority results on the 1,200 synthetic test cases.", ["Priority", "Support", "Recall", "Precision", "F1"], rows,
            widths=[1.8, 1.0, 1.1, 1.1, 1.0], align=["l", "c", "c", "c", "c"], size=9.8),
        TAB("Confusion matrix (rows: recorded priority, columns: model priority).", ["Recorded \\ model", "P1", "P2", "P3", "P4", "P5", "Total"], cm_rows,
            widths=[1.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.9], align=["l", "c", "c", "c", "c", "c", "c"], size=9.8),
        FIG(F.fig("f01_confusion_matrix.png"), "Confusion matrix of the shipped model on the synthetic hold-out set; the diagonal is correct, nearly every error is one level away.", 4.6),
        FIG(F.fig("f02_recall_per_priority.png"), "Recall for each priority on the synthetic hold-out set: highest for the non-urgent end, lowest for priority 1.", 4.6),
        P(f"Two features of the matrix matter. First, the errors are almost all adjacent: only {round((1 - F.W1) * F.N_TEST)} of {F.N_TEST:,} cases are two levels off, and none further. "
          f"Second, the two most urgent classes are the weakest. Priority 1 is rare ({F.pct(F.PRIO_SHARE[0])} of the data, {F.SUP[0]} test cases) and only {F.pct(F.REC[0])} of those were found; {F.CM[0][1]} of the {F.SUP[0]} were placed at priority 2. "
          f"Priority 2 recall is {F.pct(F.REC[1])}: {F.CM[1][2]} of {F.SUP[1]} were placed at priority 3. The model leans toward the less urgent neighbour for the sickest patients, which is the safer-looking error to avoid and the more dangerous one to make (Section 8.7)."),
        FIG(F.fig("f11_priority_distribution.png"), "Priority shares of the synthetic dataset: priority 1 is about one case in eighteen.", 4.4),
    ]


def _compare():
    names = list(F.COMP)
    rows = [[n, F.pct(F.COMP[n]["accuracy"]), F.pct(F.COMP[n]["within_one"]), F.f3(F.COMP[n]["macro_f1"]), F.f3(F.COMP[n]["qwk"]), F.pct(F.COMP[n]["top2"]), f"{F.COMP[n]['fit_seconds']:.2f}"] for n in names]
    cv = F.CV5
    lr, xg = F.COMP["Logistic regression"], F.COMP["XGBoost (shipped config)"]
    out = [
        H2("8.4 Comparison of eight model types"),
        P(f"The base paper's central exercise is to compare many classifiers on one task [{R['base']}]. The same was done here on a smaller scale: eight model types on the same fit rows and the same test rows, all uncalibrated, "
          "with settings chosen once and not tuned (no search of the kind the base paper ran with Optuna)."),
        TAB("Eight model types on the synthetic hold-out set (same split, uncalibrated).", ["Model", "Accuracy", "Within 1", "Macro F1", "QWK", "Top-2", "Fit s"], rows,
            widths=[2.2, 0.85, 0.8, 0.85, 0.7, 0.75, 0.65], align=["l", "c", "c", "c", "c", "c", "c"], size=9.2),
        FIG(F.fig("f03_model_comparison.png"), "Accuracy and macro F1 of eight model types on the synthetic hold-out set.", 5.6),
        P(f"The ranking is not the one the design implies. **Logistic regression is the best single model** ({F.pct(lr['accuracy'], 2)} accuracy, macro F1 {F.f3(lr['macro_f1'])}) and the shipped gradient-boosted configuration reaches {F.pct(xg['accuracy'], 2)} uncalibrated "
          f"(macro F1 {F.f3(xg['macro_f1'])}). The reason is in how the data were made: the label comes from an additive severity score, which a linear model can represent almost exactly, whereas trees must approximate it with steps. "
          "On real triage records, where interactions and thresholds matter, the order could be different, but this experiment cannot say so. "
          f"The comparison agrees with the literature that tree ensembles are strong on tabular data [{R['grinsztajn']}], but it does not show an advantage for them here. "
          "The choice of XGBoost for the product rested on three other reasons: an exact and fast per-patient explanation with `TreeExplainer` [" + str(R['treeshap']) + "], graceful handling of mixed binary and numeric inputs, and an established calibration recipe [" + str(R['zadrozny']) + "], [" + str(R['niculescu']) + "]. "
          "A decision tree (54.7 %) and k-nearest neighbours (62.6 %) were clearly worse; the random forest and extra trees sit near the shipped model."),
        P(f"Stability was checked two ways. Five-fold cross-validation over all {F.ROWS:,} rows gave {F.pct(cv['Logistic regression']['mean'], 2)} (sd {F.pct(cv['Logistic regression']['std'], 2)}) for logistic regression, "
          f"{F.pct(cv['Random forest']['mean'], 2)} (sd {F.pct(cv['Random forest']['std'], 2)}) for the random forest and {F.pct(cv['XGBoost (shipped config)']['mean'], 2)} (sd {F.pct(cv['XGBoost (shipped config)']['std'], 2)}) for XGBoost. "
          f"Retraining the shipped recipe on five other splits gave a mean accuracy of {F.pct(F.SEEDS['accuracy_mean'], 2)} (sd {F.pct(F.SEEDS['accuracy_std'], 2)}) and a mean macro F1 of {F.f3(F.SEEDS['macro_f1_mean'])}. "
          f"The shipped split (seed {F.SEED}, {F.pct(F.ACC, 2)}) is therefore a below-average draw by about two points; the honest summary is 'about 70 % to 72 % exact accuracy'. Differences of one to two points between model types are inside this spread."),
    ]
    if not F.REPORT:
        out.append(TAB("Accuracy of the shipped recipe on five other splits.", ["Split seed", "Accuracy", "Within 1", "Macro F1", "QWK"],
                       [[str(r["seed"]), F.pct(r["accuracy"], 2), F.pct(r["within_one"], 2), F.f3(r["macro_f1"]), F.f3(r["qwk"])] for r in F.SEEDS["runs"]],
                       widths=[1.2, 1.2, 1.2, 1.2, 1.2], align=["c"] * 5, size=9.5))
    out.append(P(f"**A ceiling.** Because the labels are the severity score plus noise, there is a best possible exact accuracy. A reader that knew the noiseless severity score would reproduce {F.pct(F.CEILING, 2)} of the recorded priorities (and {F.pct(F.X['noise_ceiling']['oracle_within_one'], 0)} within one level). "
                 f"No model can exceed about {F.pct(F.CEILING, 0)}. The shipped model's {F.pct(F.ACC, 1)} is about {(F.CEILING - F.ACC) * 100:.0f} points below that ceiling; the gap is learning error, mostly on the rare urgent classes."))
    return out


def _ablation():
    A = F.ABL
    order = ["Vitals only (8)", "Vitals + lab flags (14)", "Vitals + text flags (30)", "Report only (28)", "Fused (36)"]
    rows = [[n, str(A[n]["inputs"]), F.pct(A[n]["accuracy"]), F.pct(A[n]["within_one"]), F.f3(A[n]["macro_f1"]), F.f3(A[n]["qwk"]), F.pct(A[n]["top2"])] for n in order]
    d_v = (A["Fused (36)"]["accuracy"] - A["Vitals only (8)"]["accuracy"]) * 100
    d_r = (A["Fused (36)"]["accuracy"] - A["Report only (28)"]["accuracy"]) * 100
    return [
        H2("8.5 What fusing the report with the vitals adds"),
        P(f"The gap named in the literature survey is that surveyed models use one modality of structured data. To measure what the second modality adds, the same XGBoost configuration was trained on subsets of the 36 inputs and scored on the same synthetic test cases."),
        TAB("Modality ablation (XGBoost, uncalibrated, synthetic hold-out).", ["Inputs used", "Inputs", "Accuracy", "Within 1", "Macro F1", "QWK", "Top-2"], rows,
            widths=[2.0, 0.7, 0.85, 0.8, 0.85, 0.7, 0.7], align=["l", "c", "c", "c", "c", "c", "c"], size=9.3),
        FIG(F.fig("f04_modality_ablation.png"), "Accuracy and macro F1 for vitals only, report only and the fused record (synthetic hold-out).", 5.2),
        P(f"The fused record is {d_v:.1f} points more accurate than the vitals alone ({F.pct(A['Vitals only (8)']['accuracy'])}) and {d_r:.1f} points more accurate than the report alone ({F.pct(A['Report only (28)']['accuracy'])}). "
          f"Within-one accuracy tells the same story: {F.pct(A['Vitals only (8)']['within_one'])} for vitals, {F.pct(A['Fused (36)']['within_one'])} fused. The text flags carry most of the report's value (vitals plus text flags {F.pct(A['Vitals + text flags (30)']['accuracy'])}); the six laboratory flags add less on their own (vitals plus labs {F.pct(A['Vitals + lab flags (14)']['accuracy'])}). "
          "This supports the design, but with the same caveat as every result here: the synthetic generator draws the labels from both the vitals and the report flags, so the data were built to reward fusion. How much a real report adds is an open question that only real records can answer."),
    ]


def _calibration():
    c = F.CAL
    t = F.thr_row
    rows = [[f"{r['threshold']:.2f}", F.pct(r["coverage"]), str(r["n"]), F.pct(r["accuracy"]), F.pct(r["within_one"])] for r in F.THR]
    out = [
        H2("8.6 Calibration and the confidence threshold"),
        P(f"A triage tool shows a confidence next to the priority, so that number should mean something. Isotonic calibration on a separate split lowered the expected calibration error (10 bins, top label) only modestly, from **{F.f4(c['ece_uncalibrated'])} to {F.f4(c['ece_isotonic'])}**, "
          f"and the summed multiclass Brier score from {F.f4(c['brier_uncalibrated'])} to {F.f4(c['brier_isotonic'])}. Mean confidence rose from {F.f3(c['mean_confidence_uncalibrated'])} to {F.f3(c['mean_confidence_isotonic'])}, against an accuracy of {F.pct(F.ACC)}. "
          "The uncalibrated model was already under-confident; calibration corrected that. The reliability bins show where it is still wrong:"),
    ]
    if not F.REPORT:
        out.append(TAB("Reliability bins of the calibrated model (synthetic hold-out).", ["Confidence bin", "Cases", "Mean confidence", "Observed accuracy"],
                       [[f"{b['lo']:.1f} to {b['hi']:.1f}", str(b["n"]), F.f3(b["confidence"]), F.f3(b["accuracy"])] for b in c["bins_isotonic"]],
                       widths=[1.6, 1.0, 1.6, 1.6], align=["c", "c", "c", "c"], size=9.5))
    out += [
        FIG(F.fig("f05_calibration_reliability.png"), "Reliability diagram of the calibrated and uncalibrated model on the synthetic hold-out set.", 4.6),
        P(f"The bins from 0.5 to 0.8 are close to the diagonal. The 0.8 to 0.9 bin is over-confident: 138 cases with a mean confidence of {F.f3(c['bins_isotonic'][5]['confidence'])} were right only {F.pct(c['bins_isotonic'][5]['accuracy'])} of the time. "
          "Confidence is therefore a useful ranking signal, not a probability to quote to a patient. This is the modest end of what calibration literature reports for non-neural models [" + str(R['guo']) + "]."),
        H3("8.6.1 Accuracy against coverage"),
        P(f"The base paper accepts a diagnosis as highly probable when its probability exceeds 0.85 and reports that such predictions are more accurate than the average [{R['base']}]. The same analysis was made here: how accurate is the model on the cases where it is more confident, and how many cases are left?"),
        TAB("Accuracy of the calibrated model when only cases above a confidence threshold are kept (synthetic hold-out).", ["Threshold", "Coverage", "Cases", "Accuracy", "Within 1"], rows,
            widths=[1.1, 1.1, 0.9, 1.1, 1.1], align=["c"] * 5, size=9.5),
        FIG(F.fig("f06_threshold_coverage.png"), "Exact accuracy and coverage as the confidence threshold is raised (synthetic hold-out).", 5.0),
        P(f"Accuracy rises from {F.pct(t(0.0)['accuracy'])} for all cases to {F.pct(t(0.85)['accuracy'])} at a threshold of 0.85, but that threshold keeps only {F.pct(t(0.85)['coverage'])} of the cases; at 0.9 the figures are {F.pct(t(0.9)['accuracy'])} and {F.pct(t(0.9)['coverage'])}. "
          "ATHENA does not apply any threshold: every case gets a priority. The table shows what a 'confident cases first, others to a senior nurse' rule could look like. It was computed on the test set, so it describes the trade-off and is not a tuned operating point."),
    ]
    return out


def _safety():
    s = F.SAFE
    return [
        H2("8.7 The safety view: under-triage and missed high-risk cases"),
        P("Accuracy treats every error alike, but in triage an error that sends a sicker patient down the queue is worse than one that moves a well patient up. The errors were therefore split by direction."),
        TAB("Direction and size of the model's errors (synthetic hold-out, 1,200 cases).", ["Measure", "Value"],
            [["Under-triage: model less urgent than recorded", F.pct(s["under_triage_any"], 2)],
             ["Over-triage: model more urgent than recorded", F.pct(s["over_triage_any"], 2)],
             ["Under-triage by two or more levels", f"{F.pct(s['under_triage_2plus'], 2)} (4 cases)"],
             ["Over-triage by two or more levels", F.pct(s["over_triage_2plus"], 2)],
             [f"Recorded priority 1 placed at priority 3 or less urgent", f"{s['p1_predicted_p3_or_lower_urgency']} of {s['p1_support']}"],
             [f"High risk (P1 or P2) found at arg-max: recall / precision ({s['high_risk_support']} cases)", f"{F.pct(s['high_risk_recall'])} / {F.pct(s['high_risk_precision'])}"],
             ["High risk found when P(1) + P(2) is at least 0.4 (not implemented): recall / precision", f"{F.pct(s['high_risk_recall_at_pr_0_4'])} / {F.pct(s['high_risk_precision_at_pr_0_4'])}"]],
            widths=[5.0, 1.8], align=["l", "c"], size=9.8),
        FIG(F.fig("f13_triage_direction.png"), "Under-triage and over-triage rates of the shipped model on the synthetic hold-out set.", 4.6),
        P(f"The model under-triages {F.pct(s['under_triage_any'])} of cases and over-triages {F.pct(s['over_triage_any'])}: it errs toward the less urgent side more than twice as often as toward the more urgent. Almost all of this is one level. "
          f"For the question that matters most, 'is this patient high risk?', recall at arg-max is only {F.pct(s['high_risk_recall'])} with precision {F.pct(s['high_risk_precision'])}, so about one high-risk case in three is labelled Moderate or Low. "
          f"Raising an alarm whenever the combined probability of priorities 1 and 2 reaches 0.4 would lift recall to {F.pct(s['high_risk_recall_at_pr_0_4'])} at a precision of {F.pct(s['high_risk_precision_at_pr_0_4'])}. "
          "That rule is not in the product; it is the most direct improvement the results suggest (Chapter 10). Until then, a clinician must review every priority, which is what the override loop is for. These figures are on synthetic data and are consistent with the known tendency of triage scales themselves to miss critical illness [" + str(R['hinson']) + "]."),
    ]


def _robust():
    rows = [[f"{r['drop_rate']:.1f}" if r["drop_rate"] < 1 else "1.0 (no report)", F.pct(r["accuracy"]), F.pct(r["within_one"]), F.f3(r["macro_f1"]), F.pct(r["top2"])] for r in F.ROB]
    r1, r2, r3 = F.rob_row(0.1), F.rob_row(0.2), F.rob_row(1.0)
    return [
        H2("8.8 Robustness to missed report findings"),
        P(f"The base paper stresses that clinical records are incomplete and treats an unreported symptom as absent rather than imputing it [{R['base']}]. ATHENA follows the same rule: a report flag that the reader does not find is 0. "
          "To see what that costs, each positive report flag in the test set was removed with a given probability before scoring, imitating a reader that misses findings. The vitals were left intact."),
        TAB("Accuracy when report findings are dropped at random (shipped model, synthetic hold-out).", ["Probability a finding is dropped", "Accuracy", "Within 1", "Macro F1", "Top-2"], rows,
            widths=[2.4, 1.0, 1.0, 1.0, 1.0], align=["c"] * 5, size=9.5),
        FIG(F.fig("f07_robustness_dropped_flags.png"), "Accuracy and within-one accuracy as report findings are dropped at random.", 5.0),
        P(f"The model degrades gradually: {F.pct(r1['accuracy'])} accuracy when one finding in ten is missed, {F.pct(r2['accuracy'])} at one in five, and {F.pct(r3['accuracy'])} with no report at all (within-one {F.pct(r3['within_one'])}). "
          f"A missed finding is costly. The report reader's recall on the stress fragments is {F.pct(F.STRESS['recall'])}, which puts real use nearer the 0.1 to 0.2 rows than the 0.0 row; on wording outside the lexicon it is far lower. "
          "The result also shows why the reader is the part of the system to improve first (Chapter 10)."),
    ]


def _shap():
    rows = [[str(i + 1), LABELS.get(r["feature"], r["feature"]), F.f3(r["mean_abs_shap"])] for i, r in enumerate(F.SHAP_TOP[:10])]
    out = [
        H2("8.9 What the model relies on"),
        P("Averaging the absolute SHAP attribution over all test cases and classes gives a global picture of the inputs the model uses [" + str(R['shap']) + "], [" + str(R['treeshap']) + "]."),
    ]
    if not F.REPORT:
        out.append(TAB("Ten largest mean absolute SHAP values (synthetic hold-out).", ["Rank", "Input", "Mean |SHAP|"], rows, widths=[0.8, 3.6, 1.4], align=["c", "l", "c"], size=9.5))
    out += [
        FIG(F.fig("f08_shap_global.png"), "Mean absolute SHAP value of the fifteen most influential inputs on the synthetic hold-out set.", 5.2),
        P("Oxygen saturation, arrival mode, shortness of breath, blood pressure and respiratory rate lead, followed by ST elevation, focal weakness, raised troponin and chest pain. "
          "That is what the synthetic severity rule rewards, so the ranking is a check that the explainer reports what the model learned and that the model learned the rule; it is not clinical validation. "
          "Whether the explanation is useful to a clinician is untested."),
    ]
    return out


def _reader():
    st = F.STRESS
    return [
        H2("8.10 Report reading"),
        P(f"On the 12 generated sample reports (8 PDFs and 4 PNG scans read through OCR) the reader found every expected flag and no extra one: precision {F.pct(F.READ['precision'], 0)}, recall {F.pct(F.READ['recall'], 0)}, {F.READ['reports_read_exactly']} of {F.READ['reports']} read exactly. "
          "That figure shows that the pipeline works end to end; it does not show that real scans are solved, because these reports were written and drawn with the lexicon in view. "
          f"On the {st['cases']} hand-written stress fragments the figures are lower and more informative: precision {F.pct(st['precision'])}, recall {F.pct(st['recall'])}, {st['cases_read_exactly']} of {st['cases']} read exactly. "
          "Wording the lexicon contains (plain statements, abbreviations, laboratory values, history) was read almost perfectly; negation edge cases, OCR-damaged words and paraphrases were not (Section 7.6)."),
        P(f"Reading time per patient (`ml/eval.py`, 12 samples): mean {F.E2E['mean']:.2f} s, median {F.E2E['median']:.3f} s, maximum {F.E2E['max']:.2f} s from upload to priority. A text PDF is read in a few milliseconds; a scan takes 2 to 5 s on the CPU. "
          f"Over HTTP the median for a text PDF through to a priority is {F.lat('flow_pdf_then_triage'):.0f} ms and for a scan {F.lat('flow_scan_then_triage') / 1000:.1f} s."),
    ]


def _paper():
    b = F.BASE_PAPER_RESULTS
    rows = [
        ["Task", f"Diagnosis as an ICD-10 class ({b['classes']} classes, {b['classes_ped']} in paediatrics, {b['classes_int']} in internal medicine)", "Triage priority, 5 ordered classes, plus risk level"],
        ["Data", f"{b['cases']:,} real clinical cases ({b['internal']} internal medicine, {b['pediatrics']:,} paediatrics); external check on {b['ext_cases']} cases", f"{F.ROWS:,} synthetic rows; no real data, no external check"],
        ["Input", f"{b['parameters']} typed symptom, sign and laboratory indicators; missing = absent", "Scanned report (OCR + lexicon) fused with 8 vitals into 36 inputs; missing = absent"],
        ["Models compared", f"{b['algorithms']} algorithms, Optuna tuning ({b['trials']} trials each)", "8 model types, settings not tuned"],
        ["Best exact accuracy", f"{b['best_int'][0]} {F.pct(b['best_int'][1], 2)} (internal medicine); {b['best_ped'][0]} {F.pct(b['best_ped'][1], 2)} (paediatrics)", f"Logistic regression {F.pct(F.COMP['Logistic regression']['accuracy'], 2)}; shipped XGBoost {F.pct(F.ACC, 2)} (synthetic)"],
        ["Ranked output", f"TOP-3: mean {F.pct(b['top3_mean_int'], 2)} / {F.pct(b['top3_mean_ped'], 2)}; best {F.pct(b['top3_best_int'], 2)} / {F.pct(b['top3_best_ped'], 2)}", f"Top-2 {F.pct(F.TOP2)} (2 of 5 classes; not the same difficulty as 3 of 87)"],
        ["High-confidence threshold", f"0.85, 'highly probable'; sensitivity analysis 0.70 to 0.95", f"Threshold table (Section 8.6): at 0.85 coverage {F.pct(F.thr_row(0.85)['coverage'])}, accuracy {F.pct(F.thr_row(0.85)['accuracy'])}"],
        ["Explanation", "SHAP and LIME, global, by ICD-10 block", "SHAP only, per patient, shown beside each decision; no LIME"],
        ["Incomplete data", "No imputation; analysis of six kinds of incompleteness", f"No imputation; dropped-finding experiment (Section 8.8): {F.pct(F.rob_row(0.2)['accuracy'])} at 20 % dropped"],
        ["Statistics", "Bootstrap 95 % intervals, McNemar tests", "Five splits and 5-fold cross-validation; no significance test"],
        ["Scanned documents", "Not handled", "Reader recall 100 % on generated samples, " + F.pct(F.STRESS["recall"]) + " on stress fragments"],
        ["Time per case", "Not reported in the sections read", f"Median {F.lat('flow_pdf_then_triage'):.0f} ms (PDF) and {F.lat('flow_scan_then_triage') / 1000:.1f} s (scan) over HTTP"],
    ]
    return [
        H2("8.11 Comparison with the base paper"),
        P(f"**The two studies are not comparable on accuracy, and no claim is made that ATHENA outperforms the base paper.** They differ in task (diagnosis among {b['classes']} ICD-10 classes against a five-level priority), in data (real clinical cases against a synthetic generator), in input (typed indicators against a scanned report fused with vitals), and in metric difficulty. "
          f"A five-class problem with an ordinal structure and a rule-generated label is a different, easier kind of problem than 87-class diagnosis from incomplete real records, so a higher or lower accuracy in either direction would prove nothing. The table sets the two side by side by feature."),
        TAB("The base paper [" + str(R['base']) + "] and ATHENA, feature by feature.", ["Aspect", "Base paper", "ATHENA (synthetic data)"], rows, widths=[1.3, 2.9, 2.6], align=["l", "l", "l"], size=9.0),
        FIG(F.fig("f12_base_paper_context.png"), "Headline figures of the base paper and the values measured here, with the task and data of each stated; the two sets of numbers are not comparable.", 5.6),
        P("Where ATHENA does follow the base paper it adopts four ideas: comparing several algorithms on one task, reading the probabilities as a ranking (top-k) rather than only the arg-max, studying a high-confidence threshold, and treating an unreported finding as absent. "
          "Where it goes beyond the paper is the intake of scanned reports, fusion with vitals, a five-level target, calibrated confidence, a per-patient explanation shown with the decision, the clinician override record, and the measured processing time. "
          "Where it falls short is evidence: the base paper used real cases, tuned 19 algorithms, reported intervals and tests, and validated on an external facility. ATHENA did none of these."),
    ]


def _samples():
    case_rows = [
        ["A: sample report 01 (chest pain, ambulance)", "Age 58, HR 112, BP 96/60, SpO2 93, 36.9 C, RR 22", "chest pain, shortness of breath, ST elevation, diabetes, hypertension, cardiac disease, troponin raised, lactate raised",
         "P1 Critical, High, confidence 1.00", "ST elevation +3.11; troponin +2.19; lactate +1.51; heart rate 112 +1.49; SpO2 93 +0.97"],
        ["B: sample report 03 (fever, cough, low oxygen)", "Age 66, HR 118, BP 104/64, SpO2 89, 39.1 C, RR 28", "shortness of breath, fever, lung infiltrate, COPD, diabetes, WBC raised, lactate raised",
         "P1 Critical, High, confidence 0.74 (P2 0.26)", "SpO2 89 +2.92; lactate +1.76; resp. rate 28 +1.28; heart rate 118 +0.86; lung infiltrate +0.68"],
        ["C: sample report 07 (minor cold, walk-in)", "Age 22, HR 74, BP 118/74, SpO2 99, 36.8 C, RR 15", "none found",
         "P5 Non-urgent, Low, confidence 0.98 (P4 0.02)", "arrival mode walk-in +0.65; no trauma +0.25; SpO2 99 +0.20; systolic BP 118 +0.19; no chest pain +0.19"],
    ]
    return [
        H2("8.12 Sample inputs and outputs"),
        P("Three illustrative cases were run through the real reader and the shipped model with the project environment (`backend.app.services.extract` and `triage.predict`) on the generated sample reports, using the vitals that accompany each sample. "
          "They are chosen to show a clear critical case, a case the model is less sure of, and a trivial one; they are not a test set. All three are synthetic documents."),
        TAB("Three illustrative cases (computed with the shipped model; synthetic sample data).", ["Case", "Vitals entered", "Flags read from the report", "Model output", "Largest explanation items"], case_rows,
            widths=[1.25, 1.2, 1.7, 1.2, 1.55], align=["l", "l", "l", "l", "l"], size=8.5),
        P("Case A is the screen shown in Section 8.2: the reader found eight flags, including the ST elevation and two raised laboratory values from page 2, and the model is certain. "
          "Case B reaches priority 1 mainly through low oxygen saturation, raised lactate and a fast breathing rate, but the second-most probable class takes 26 % of the probability, which is the kind of case a clinician would look at twice. "
          "In case C every finding flag is zero and the model returns the lowest priority with high confidence; here the arrival mode (walk-in) is the largest single factor, an effect of how the synthetic data were generated more than a clinical truth. "
          "A fourth case, the generated scan of an ankle sprain (sample 12), was read through OCR in 7.6 s on the first call in a fresh process, found one flag (trauma) and gave priority 4 with confidence 0.66."),
        P("The 12 sample cases seeded into the queue come from the synthetic hold-out rows with their recorded priority. The shipped model matches that recorded priority for 8 of the 12 (67 %); the four misses (sample cases 01, 02, 09 and 12) are all one level away and all recorded as priority 4, which is the kind of error the noise in the labels produces."),
    ]


def _cases():
    cm = F.CM
    out = [
        H2("8.13 Success and failure analysis"),
        H3("8.13.1 Where the system works"),
        B("**The pipeline works end to end.** A PDF or scan goes in; findings with pages, a priority, a calibrated confidence and an explanation come out in about 30 ms for a text PDF and about 2 s for a scan (Section 7.7).",
          "**Errors are close.** " + F.pct(F.W1, 2) + " of priorities are within one level of the recorded one on the synthetic hold-out, and the quadratic weighted kappa is " + F.f3(F.QWK) + ".",
          "**Fusion helps** on this data: " + f"{(F.ABL['Fused (36)']['accuracy'] - F.ABL['Vitals only (8)']['accuracy']) * 100:.0f} points over vitals alone.",
          "**The explanation names the right things.** The largest attributions for the critical sample are ST elevation, troponin and lactate; globally the model relies on oxygen saturation, arrival mode, breathlessness and blood pressure, as the generating rule does.",
          "**The reader is strong on what it knows:** negated statements, abbreviations, laboratory ranges and pages are handled, and 12 of 12 generated reports (including four OCR scans) were read exactly."),
        H3("8.13.2 Where it fails"),
        B(f"**The most urgent classes are the weakest.** {cm[0][1]} of {F.SUP[0]} priority-1 cases went to priority 2 (recall {F.pct(F.REC[0])}), and {cm[1][2]} of {F.SUP[1]} priority-2 cases went to priority 3 (recall {F.pct(F.REC[1])}). The cut points between these classes lie where the added noise matters most and the classes are rare.",
          f"**High-risk recall is {F.pct(F.SAFE['high_risk_recall'])}** at arg-max; one high-risk case in three would be labelled Moderate or Low.",
          "**Over-confidence in one band.** Cases scored 0.8 to 0.9 were right about two times in three.",
          f"**A linear model does as well or better** ({F.pct(F.COMP['Logistic regression']['accuracy'])} against {F.pct(F.COMP['XGBoost (shipped config)']['accuracy'])}), so the added machinery is not justified by the synthetic data alone.",
          "**The reader misses what the lexicon does not contain,** and a few spurious or lost flags follow from the negation rules (Section 7.6). A missed finding lowers accuracy by about three points for every ten per cent of findings dropped.",
          "**The explanation wording is inverted** in the API for low-priority predictions (Section 7.6), and the interface cannot correct a misread finding.",
          "**Nothing here is a real-world test.** The model was never shown a real patient."),
        P("The pattern of failure is consistent with the data rather than with a bug in the model. The recorded priority is the severity score plus noise of standard deviation 0.4, cut at four thresholds; cases close to a threshold carry a label that even a perfect reader of the score gets wrong about one time in seven. "
          "The classes at the sick end are rare, so there are few examples to learn their boundary from."),
    ]
    return out


def _limits():
    return [
        H2("8.14 Limitations of the evaluation"),
        B("**Synthetic data throughout.** Every accuracy, recall and calibration figure describes recovery of a known rule. The study cannot say how ATHENA would perform on real patients, and it should not be quoted as an accuracy for triage.",
          "**Circular design.** The same author-written assumptions generate the data, the sample reports and the lexicon; the 100 % reading score and the benefit of fusion are partly built in.",
          "**One dataset, one generator, one split for the headline numbers.** Five other splits and cross-validation show a spread of about one point, and the shipped split is two points below their mean.",
          "**Developer-written stress fragments** and a small number of generated scans; no independent clinical text and no real scans.",
          "**Threshold, safety and robustness analyses were run on the test set** and describe trade-offs; none was tuned.",
          "**No external validation, no prospective study, no clinician review** of the explanations, and no comparison with a nurse's own triage or with a standard scale such as ESI [" + str(R['esi']) + "].",
          "**No significance tests,** and the model settings were not searched, unlike the base paper's 100-trial tuning."),
    ]


def _objectives():
    rows = [
        ["1. Build an OCR stage that converts scanned reports to machine-readable text", "Met",
         "PDF text layer plus local RapidOCR (PaddleOCR-family models on ONNX Runtime) for scans; 12 of 12 generated reports read; scans take 2 to 5 s"],
        ["2. Apply a medical language model to extract symptoms, findings and history", "Partly met",
         f"A rule-based lexicon of 22 terms with negation and 6 lab rules was used instead of BioBERT [{R['biobert']}]; precision {F.pct(F.STRESS['precision'])}, recall {F.pct(F.STRESS['recall'])} on stress fragments, 100 % on generated samples"],
        ["3. Combine text-derived features with vitals in a single representation", "Met", "36-input fused record (8 vitals + 28 report flags), shown side by side in the interface"],
        ["4. Train a model that assigns a risk level and a triage priority", "Met on synthetic labels",
         f"Calibrated XGBoost, priority 1 to 5 and High/Moderate/Low; {F.pct(F.ACC)} exact, {F.pct(F.W1)} within one level on synthetic hold-out"],
        ["5. Add an explainability layer showing which findings drove the priority", "Met", "Per-patient SHAP beside every decision, strongest first; no LIME; usefulness to clinicians untested"],
        ["6. Evaluate accuracy against clinician-assigned priority and measure processing time per patient", "Partly met",
         f"Accuracy measured only against the synthetic recorded priority, not clinicians; time per patient measured (median {F.lat('flow_pdf_then_triage'):.0f} ms for a PDF, {F.lat('flow_scan_then_triage') / 1000:.1f} s for a scan)"],
    ]
    extra = [["Batch brief: BioBERT, RAG, multi-agent orchestration, six disease-risk models, MongoDB, Node.js and Flask", "Not built",
              "Replaced by a lexicon, no RAG, a single pipeline, no disease models, SQLite, and FastAPI with React; listed as future work"]]
    return [
        H2("8.15 Objectives versus outcomes"),
        TAB("The six objectives of the project against what was achieved.", ["Objective", "Status", "Evidence"], rows + extra, widths=[2.4, 1.0, 3.4], align=["l", "c", "l"], size=9.0),
        P("Taken together, the project delivered a working, tested, honestly evaluated decision-support prototype whose weakest links are the ones the batch brief most wanted: a medical language model for reading reports, and accuracy against real clinician judgement. "
          "Both remain open."),
    ]


def blocks():
    out = [H1("CHAPTER 8: RESULTS AND OUTPUT SCREENS"),
           P("This chapter reports what was measured and what the running application shows. Section 8.1 describes the set-up and the data, Section 8.2 presents the output screens, Sections 8.3 to 8.9 give the triage-model results (headline metrics, eight model types, "
             "the effect of fusing the report with the vitals, calibration and confidence, the safety view, robustness to missed findings and what the model relies on), Section 8.10 the report-reading results, Section 8.11 the comparison with the base paper, "
             "Sections 8.12 and 8.13 sample output and the analysis of successes and failures, and Sections 8.14 and 8.15 the limits of the evaluation and the objectives against the outcomes. "
             "Every model figure is on seeded synthetic data. Where a result is weak it is reported as weak.")]
    for part in (_setup, _screens, _headline, _compare, _ablation, _calibration, _safety, _robust, _shap, _reader, _paper, _samples, _cases, _limits, _objectives):
        out += part()
    if F.REPORT:   # compact report: some charts stay in the results document (14.RESULTS)
        out = [b for b in out if _fig_name(b) not in ("f11_priority_distribution.png", "f13_triage_direction.png", "f12_base_paper_context.png")]
        out = _pair_up(out, [("f01_confusion_matrix.png", "f02_recall_per_priority.png"), ("f05_calibration_reliability.png", "f06_threshold_coverage.png")])
    return out
